"use client";

import { useState } from "react";
import { TextSkeleton } from "@/components/naseem-ui/elements/text-skeleton";
import { Button } from "@/components/ui/button";

const TextSkeletonDemo = () => {
  const [loading, setLoading] = useState(true);

  return (
    <div className="flex w-full max-w-sm flex-col gap-6">
      <div className="space-y-3">
        <p className="text-xs text-muted-foreground">text-xs</p>
        {loading ? (
          <TextSkeleton className="w-3/4 text-xs" />
        ) : (
          <p className="text-xs">Small text line using xs size</p>
        )}

        <p className="text-xs text-muted-foreground">text-sm</p>
        {loading ? (
          <TextSkeleton className="w-full text-sm" />
        ) : (
          <p className="text-sm">Standard text line using the default size</p>
        )}

        <p className="text-xs text-muted-foreground">text-lg</p>
        {loading ? (
          <TextSkeleton className="w-1/2 text-lg" />
        ) : (
          <p className="text-lg">Larger heading-style text</p>
        )}
      </div>

      <Button size="sm" onClick={() => setLoading(!loading)}>
        {loading ? "Show Content" : "Show Skeleton"}
      </Button>
    </div>
  );
};

export default TextSkeletonDemo;
